const sent = /const amount = (\w+)\(\);/.exec(src)?.[1];
const cart = { items: [{ price: 30 }, { price: 20 }], discount: 50 * 0.1 }; // after SAVE10
const subtotal = () => cart.items.reduce((s, i) => s + i.price, 0);
const total = () => subtotal() - cart.discount;
const amount = { subtotal, total }[sent]?.();

const srv = spawn(process.execPath, [path.join(APP, 'server.mjs')], { stdio: 'inherit' });
const wait = async () => {
  for (let i = 0; i < 50; i++) {
    try { await fetch(BASE + '/api/orders'); return; } catch { await new Promise((r) => setTimeout(r, 100)); }
  }
  throw new Error('server never came up');
};

let fail = 0;
const check = (what, got, want) => {
  const ok = JSON.stringify(got) === JSON.stringify(want);
  if (!ok) fail++;
  console.log(`${ok ? 'ok  ' : 'NO  '}${what}: expected ${JSON.stringify(want)}, got ${JSON.stringify(got)}`);
};

try {
  await wait();
  check('amount app.js posts (order.amount)', amount, 45);

  const res = await fetch(BASE + '/api/orders', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ items: ['guji-250', 'huila-250'], code: 'SAVE10', amount }),
  });
  const order = await res.json();
  check('POST /api/orders status', res.status, 201);
  check('server-side expected total', order.expected, 45);
  check('recorded amount matches expected', order.amount, order.expected);

  // an unknown code must still be rejected, and not as a 500
  const bad = await fetch(BASE + '/api/orders', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ items: ['guji-250'], code: 'NOPE', amount: 30 }),
  });
  check('unknown code is a client error, not 500', bad.status, 400);
} finally {
  srv.kill();
}
console.log(fail ? `\n${fail} check(s) failed` : '\nall checks passed');
process.exit(fail ? 1 : 0);

const cart = { items: [{ sku: 'guji-250', price: 30 }, { sku: 'huila-250', price: 20 }], code: null, discount: 0 };
const money = (n) => '$' + n.toFixed(2);
const subtotal = () => cart.items.reduce((s, i) => s + i.price, 0);
const total = () => subtotal() - cart.discount;
let lastOrder = { status: 'none', amount: null };

function render() {
  document.getElementById('subtotal').textContent = money(subtotal());
  document.getElementById('discount-line').textContent = cart.discount ? '-' + money(cart.discount) : '$0.00';
  document.getElementById('total').textContent = money(total());
}

document.getElementById('discount').addEventListener('submit', (e) => {
  e.preventDefault();
  const code = document.getElementById('code').value.trim().toUpperCase();
  const msg = document.getElementById('discount-msg');
  if (code === 'SAVE10') {
    cart.code = code;
    cart.discount = subtotal() * 0.1;
    msg.textContent = 'SAVE10 applied: 10% off.';
  } else {
    cart.code = null;
    cart.discount = 0;
    msg.textContent = 'That code isn\'t valid.';
  }
  render();
});

document.getElementById('place').addEventListener('click', async () => {
  const amount = subtotal();
  lastOrder = { status: 'sending', amount };
  await fetch('/api/orders', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ items: cart.items.map((i) => i.sku), code: cart.code, amount }),
  });
  lastOrder.status = 'placed';
  document.getElementById('result').textContent = 'Order placed. Thank you!';
});

render();

// What the app knows to be true, for Beam.
if (window.beam) {
  beam.expose('cart.total', () => total());
  beam.expose('order.amount', () => lastOrder.amount);
  beam.expose('order.status', () => lastOrder.status);
}
